const getWidthForCount = (itemWidths, moreWidth, gap, count, total) => {
  let usedWidth = 0;
  for (let i = 0; i < count; i++) {
    usedWidth += itemWidths[i] + (i > 0 ? gap : 0);
  }

  if (count < total) {
    usedWidth += gap + moreWidth;
  }

  return usedWidth;
};

/**
 * 根据容器宽度与各 item / more 宽度，计算可露出的 item 数量。
 * @param {object} options
 * @param {number} options.containerWidth
 * @param {number[]} options.itemWidths
 * @param {number} options.moreWidth
 * @param {number} [options.gap=8]
 * @param {'asc'|'desc'} [options.strategy='asc']
 * @param {number} [options.safetyGap=2]
 * @returns {number}
 */
const computeVisibleCount = ({ containerWidth, itemWidths, moreWidth, gap = 8, strategy = 'asc', safetyGap = 2 }) => {
  const widths = Array.isArray(itemWidths) ? itemWidths : [];
  const total = widths.length;

  if (total === 0) {
    return 0;
  }

  if (!(containerWidth > 0)) {
    return Math.min(1, total);
  }

  const more = moreWidth > 0 ? moreWidth : 0;
  const maxCount = total;
  let count = 1;

  if (strategy === 'desc') {
    count = maxCount;
    while (count > 1) {
      const usedWidth = getWidthForCount(widths, more, gap, count, total);
      if (usedWidth + safetyGap <= containerWidth) {
        break;
      }
      count -= 1;
    }
  } else {
    count = 1;
    while (count < maxCount) {
      const nextCount = count + 1;
      const usedWidth = getWidthForCount(widths, more, gap, nextCount, total);
      if (usedWidth + safetyGap > containerWidth) {
        break;
      }
      count = nextCount;
    }
  }

  return Math.max(1, count);
};

export default computeVisibleCount;
